#![allow(clippy::module_inception)]

mod tool;

pub use tool::Tool;
pub(crate) use tool::ToolFn;

use bevy::prelude::*;
use schemars::JsonSchema;
use serde::Deserialize;

#[derive(Component)]
#[relationship(relationship_target = AgentTools)]
pub struct ToolOf(Entity);

#[derive(Component)]
#[relationship_target(relationship = ToolOf)]
pub struct AgentTools(Vec<Entity>);

/// The input of a tool system: `fn my_tool(In(input): In<ToolInput<Args>>, ...) -> Output`.
pub struct ToolInput<A = NoArgs> {
    /// The agent that called the tool.
    pub agent: Entity,
    /// The arguments generated by the model.
    pub args: A,
}

/// Arguments of a tool that takes none.
#[derive(Deserialize, JsonSchema)]
pub struct NoArgs {}

pub(crate) struct RawToolCall {
    pub(crate) entity: Entity,
    pub(crate) raw_args: String,
    pub(crate) raw_responder: oneshot::Sender<String>,
    pub(crate) call: ToolFn,
}
